def get_flat_dependant(
    dependant: Dependant,
    *,
    skip_repeats: bool = False,
    visited: Optional[List[CacheKey]] = None,
) -> Dependant:
    if visited is None:
        visited = []

    flat_dependant = Dependant()
    flat_dependant.cache_key = dependant.cache_key
    flat_dependant.call = dependant.call
    flat_dependant.name = dependant.name
    flat_dependant.security_scopes = dependant.security_scopes
    flat_dependant.use_cache = dependant.use_cache
    flat_dependant.path = dependant.path
    flat_dependant.request_param_name = dependant.request_param_name
    flat_dependant.websocket_param_name = dependant.websocket_param_name
    flat_dependant.http_connection_param_name = dependant.http_connection_param_name
    flat_dependant.response_param_name = dependant.response_param_name
    flat_dependant.background_tasks_param_name = dependant.background_tasks_param_name
    flat_dependant.security_scopes_param_name = dependant.security_scopes_param_name

    for param in dependant.path_params:
        if (param, "path") not in visited:
            visited.append((param, "path"))
            flat_dependant.path_params.append(param)

    for param in dependant.query_params:
        if (param, "query") not in visited:
            visited.append((param, "query"))
            flat_dependant.query_params.append(param)

    for param in dependant.header_params:
        if (param, "header") not in visited:
            visited.append((param, "header"))
            flat_dependant.header_params.append(param)

    for param in dependant.cookie_params:
        if (param, "cookie") not in visited:
            visited.append((param, "cookie"))
            flat_dependant.cookie_params.append(param)

    for param in dependant.body_params:
        if (param, "body") not in visited:
            visited.append((param, "body"))
            flat_dependant.body_params.append(param)

    for sub_dependant in dependant.dependencies:
        if sub_dependant.cache_key not in visited:
            visited.append(sub_dependant.cache_key)
            flat_sub_dependant = get_flat_dependant(sub_dependant, skip_repeats=skip_repeats, visited=visited)
            flat_dependant.dependencies.append(flat_sub_dependant)

    for security_requirement in dependant.security_requirements:
        flat_dependant.security_requirements.append(security_requirement)

    return flat_dependant
