def get_flat_dependant(
    dependant: Dependant,
    *,
    skip_repeats: bool = False,
    visited: Optional[List[CacheKey]] = None,
) -> Dependant:
    if visited is None:
        visited = []

    flat_dependant = Dependant()
    visited.append(dependant.cache_key)

    for param_type in [
        "path_params",
        "query_params",
        "header_params",
        "cookie_params",
        "body_params",
    ]:
        for field in getattr(dependant, param_type):
            if field not in getattr(flat_dependant, param_type):
                getattr(flat_dependant, param_type).append(field)

    for sub_dependant in dependant.dependencies:
        if sub_dependant.cache_key not in visited:
            sub_flat_dependant = get_flat_dependant(
                sub_dependant, skip_repeats=skip_repeats, visited=visited
            )
            for param_type in [
                "path_params",
                "query_params",
                "header_params",
                "cookie_params",
                "body_params",
            ]:
                for field in getattr(sub_flat_dependant, param_type):
                    if field not in getattr(flat_dependant, param_type):
                        getattr(flat_dependant, param_type).append(field)
            flat_dependant.dependencies.append(sub_flat_dependant)

    return flat_dependant
